class.description:
The server passes this request to the handler declared with [method Netw.configure_admission]. A requested [member username] does not verify an account.
[codeblocks]
[gdscript]
func admit(request: NetwJoinRequest) -> Error:
    if request.identities.is_empty():
        return ERR_UNAUTHORIZED
    return OK
[/gdscript]
[csharp]
private Error Admit(Variant value)
{
    using var request = NetwJoinRequest.From(value);
    return request.Identities.Length == 0
        ? Error.Unauthorized : Error.Ok;
}
[/csharp]
[/codeblocks]
